-- Apply with `supabase db push` or in the Supabase SQL Editor.
-- Staff and assignment rows are provisioned only by a trusted server/admin process.
create extension if not exists citext;
create table public.departments (id uuid primary key default gen_random_uuid(), name text not null unique check (char_length(name) between 2 and 120), code text not null unique check (code ~ '^[A-Z0-9_]{2,32}$'), created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null check (char_length(trim(full_name)) between 2 and 100), username citext not null unique check (username ~ '^[A-Za-z0-9_]{3,30}$'), phone text not null check (phone ~ '^\+[1-9][0-9]{7,14}$'), residential_address text not null check (char_length(trim(residential_address)) between 10 and 300), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.staff_profiles (user_id uuid primary key references auth.users(id) on delete cascade, department_id uuid not null references public.departments(id) on delete restrict, role text not null check (role in ('staff','supervisor','administrator')), active boolean not null default true, provisioned_at timestamptz not null default now());
create table public.complaints (id uuid primary key default gen_random_uuid(), citizen_id uuid not null references public.profiles(id) on delete restrict, department_id uuid references public.departments(id) on delete set null, title text not null check (char_length(trim(title)) between 5 and 160), description text not null check (char_length(trim(description)) between 10 and 5000), category text not null check (char_length(trim(category)) between 2 and 80), severity smallint not null default 1 check (severity between 1 and 5), status text not null default 'submitted' check (status in ('submitted','acknowledged','in_progress','resolved','closed','rejected')), latitude numeric(9,6), longitude numeric(9,6), photo_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check ((latitude is null and longitude is null) or (latitude between -90 and 90 and longitude between -180 and 180)), check (photo_path is null or photo_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[^/]+$'));
create table public.complaint_assignments (id uuid primary key default gen_random_uuid(), complaint_id uuid not null references public.complaints(id) on delete cascade, staff_user_id uuid not null references public.staff_profiles(user_id) on delete restrict, assigned_by uuid not null references public.staff_profiles(user_id) on delete restrict, assigned_at timestamptz not null default now(), unassigned_at timestamptz, unique (complaint_id,staff_user_id,assigned_at));
create table public.complaint_status_history (id uuid primary key default gen_random_uuid(), complaint_id uuid not null references public.complaints(id) on delete cascade, previous_status text, new_status text not null check (new_status in ('submitted','acknowledged','in_progress','resolved','closed','rejected')), note text check (char_length(note) <= 2000), changed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
create index complaints_citizen_idx on public.complaints(citizen_id); create index complaints_department_idx on public.complaints(department_id); create index assignment_staff_active_idx on public.complaint_assignments(staff_user_id) where unassigned_at is null; create index history_complaint_idx on public.complaint_status_history(complaint_id,created_at desc);
create function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
create trigger profiles_updated before update on public.profiles for each row execute procedure public.set_updated_at(); create trigger complaints_updated before update on public.complaints for each row execute procedure public.set_updated_at();
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.raw_user_meta_data ? 'full_name' then insert into public.profiles(id,full_name,username,phone,residential_address) values(new.id,new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'username',new.raw_user_meta_data->>'phone',new.raw_user_meta_data->>'residential_address'); end if; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create function public.validate_assignment() returns trigger language plpgsql set search_path='' as $$ declare complaint_department uuid; assignee_department uuid; assigner_role text; begin select department_id into complaint_department from public.complaints where id=new.complaint_id; select department_id into assignee_department from public.staff_profiles where user_id=new.staff_user_id and active=true; select role into assigner_role from public.staff_profiles where user_id=new.assigned_by and active=true; if complaint_department is null or assignee_department is distinct from complaint_department or assigner_role not in ('supervisor','administrator') then raise exception 'invalid complaint assignment'; end if; return new; end; $$;
create trigger assignment_is_authorised before insert on public.complaint_assignments for each row execute procedure public.validate_assignment();
create function public.is_active_staff() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.staff_profiles where user_id=auth.uid() and active=true) $$;
create function public.can_access_department(target uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.staff_profiles where user_id=auth.uid() and active=true and (role='administrator' or department_id=target)) $$;
revoke all on function public.is_active_staff() from public,anon; revoke all on function public.can_access_department(uuid) from public,anon; grant execute on function public.is_active_staff() to authenticated; grant execute on function public.can_access_department(uuid) to authenticated;
alter table public.departments enable row level security; alter table public.profiles enable row level security; alter table public.staff_profiles enable row level security; alter table public.complaints enable row level security; alter table public.complaint_assignments enable row level security; alter table public.complaint_status_history enable row level security;
grant select on public.departments to authenticated; grant select,update on public.profiles to authenticated; grant select on public.staff_profiles to authenticated; grant select,insert,update on public.complaints to authenticated; grant select on public.complaint_assignments to authenticated; grant select on public.complaint_status_history to authenticated;
create policy "read departments" on public.departments for select to authenticated using (true);
create policy "read own profile" on public.profiles for select to authenticated using (id=auth.uid()); create policy "update own profile" on public.profiles for update to authenticated using (id=auth.uid()) with check (id=auth.uid()); create policy "read own staff record" on public.staff_profiles for select to authenticated using(user_id=auth.uid());
create policy "citizen reads own complaints" on public.complaints for select to authenticated using(citizen_id=auth.uid()); create policy "staff reads department complaints" on public.complaints for select to authenticated using(public.can_access_department(department_id)); create policy "citizen creates own complaint" on public.complaints for insert to authenticated with check(citizen_id=auth.uid() and department_id is null); create policy "citizen updates draft complaint" on public.complaints for update to authenticated using(citizen_id=auth.uid() and status='submitted' and department_id is null) with check(citizen_id=auth.uid() and status='submitted' and department_id is null); create policy "staff updates authorised complaint" on public.complaints for update to authenticated using(public.can_access_department(department_id)) with check(public.can_access_department(department_id));
create policy "staff reads relevant assignments" on public.complaint_assignments for select to authenticated using(staff_user_id=auth.uid() or exists(select 1 from public.complaints c where c.id=complaint_id and public.can_access_department(c.department_id))); create policy "citizen or staff reads history" on public.complaint_status_history for select to authenticated using(exists(select 1 from public.complaints c where c.id=complaint_id and (c.citizen_id=auth.uid() or public.can_access_department(c.department_id))));
-- No browser policies for staff provisioning, assignments, or history mutations.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('complaint-photos','complaint-photos',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "upload own complaint photo" on storage.objects for insert to authenticated with check(bucket_id='complaint-photos' and (storage.foldername(name))[1]=(select auth.uid()::text) and array_length(storage.foldername(name),1)=2); create policy "read authorised complaint photo" on storage.objects for select to authenticated using(bucket_id='complaint-photos' and ((storage.foldername(name))[1]=(select auth.uid()::text) or exists(select 1 from public.complaints c where c.photo_path=name and public.can_access_department(c.department_id)))); create policy "delete own unlinked complaint photo" on storage.objects for delete to authenticated using(bucket_id='complaint-photos' and (storage.foldername(name))[1]=(select auth.uid()::text) and not exists(select 1 from public.complaints where photo_path=name));
